        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(theme.qcolor(t.fill_2))
        p.drawRoundedRect(QRectF(self.rect()), 9, 9)
        p.drawPixmap(QPointF(6, 3.5), icons.pixmap(self._icon, t.text_3, 11))
