        self.empty.setContentsMargins(18, 14, 18, 18)
        self.empty.hide()
        self.body_lay.addWidget(self.empty)
        bind(store.sessions_changed, self, lambda _s: self._rebuild())
        self._rebuild()

    # ---- the commands
    def _actions(self) -> List[Cmd]:
        s = store
