    closed = Signal()

    def __init__(
        self,
        window: QWidget,
        key: str,
        title: str = "",
        width: int = 560,
        on_submit: Optional[Callable[[], None]] = None,
        body_margins: Tuple[int, int, int, int] = (22, 10, 22, 20),
        title_icon: str = "",
