                ico.setPixmap(icons.pixmap(icon, theme.tokens().text_2, 15))
                hl.addWidget(ico)
            self.title_lb = Text(title, theme.FS_H, 600, wrap=False)
            hl.addWidget(self.title_lb, 1)
