    {"id": "files", "label": "Files", "icon": "folder-tree", "key": "2"},
    {"id": "terminal", "label": "Terminal", "icon": "square-terminal", "key": "3"},
    {"id": "preview", "label": "Preview", "icon": "app-window", "key": "4"},
    {"id": "tasks", "label": "Tasks", "icon": "list-checks", "key": "5"},
