        super().leaveEvent(e)


class WelcomeChip(QPushButton):
    """``.folder-chip``: a recent folder as a 26px pill; ``on`` marks the chosen one."""

    def __init__(self, text: str, tooltip: str, parent: Optional[QWidget] = None) -> None:
