has_qt() { "$1" -c 'import PyQt6.QtWebEngineWidgets' >/dev/null 2>&1; }
python_candidates() {
  [ -n "${PILCROW_PYTHON:-}" ] && echo "$PILCROW_PYTHON"
  [ -x /usr/bin/python3 ] && echo /usr/bin/python3
