    const isUrl = /^[a-z][a-z0-9+.-]*:\/\//i.test(target) || target.startsWith('mailto:');
    const [cmd, args] = isUrl ? ['rundll32.exe', ['url.dll,FileProtocolHandler', target]] : ['explorer.exe', [target.replace(/\//g, '\\')]];
