function request(url, headers, env) {
  const ca = extraCa(env);
  const rejectUnauthorized = env.NODE_TLS_REJECT_UNAUTHORIZED !== '0';
  const proxy = proxyFor(url, env);
  return new Promise((resolve, reject) => {
    const done = (res) => {
      let body = '';
