    if (e.key === 'ArrowUp' && hist.length && (text === '' || histPos >= 0) && ta.current?.selectionStart === 0) {
      e.preventDefault();
      const p = Math.min(hist.length - 1, histPos + 1);
      setHistPos(p);
      setText(hist[p]);
      return;
    }
    if (e.key === 'ArrowDown' && histPos >= 0 && ta.current?.selectionStart === text.length) {
      e.preventDefault();
