    };
  }, []);

  const step = (d: number) => {
    if (!count) return;
    const i = (index + d + count) % count;
    setIndex(i);
    paintCurrent(i, true);
  };

  if (!supported) return null;
  return (
    <div className="findbar" role="search" ref={box}>
      <Search size={14} className="findbar-ico" />
      <input
        ref={input}
        autoFocus
        value={q}
        placeholder="Find in conversation"
        spellCheck={false}
        onChange={(e) => setQ(e.target.value)}
        onKeyDown={(e) => {
