            {browse.dirs.map((d) => (
              <button key={d.path} className="browser-item" onClick={() => nav(d.path)} onDoubleClick={() => onPick(d.path)}>
                {d.repo ? <FolderGit2 size={14} /> : <Folder size={14} />}
