    }
  };
  const toggle = (on: boolean) => call('schedules.toggle', { id: s.id, enabled: on }).catch(() => {});
  const del = () =>
    confirmAction({
      title: `Delete the schedule “${s.name}”?`,
      body: 'Its past runs stay in the inbox.',
      confirm: 'Delete schedule',
