              <Spinner size={11} />
            </div>
          )}
          {list.map((e) =>
            e.type === 'dir' ? (
              <TreeDir key={e.path} path={e.path} depth={root ? depth : depth + 1} st={st} update={update} onOpen={onOpen} active={active} nonce={nonce} />
