      )}
    </div>
  );
}

function SubAgentRow({ t, now }: { t: TaskInfo; now: number }) {
  const st: AgentState = t.status === 'running' ? 'running' : t.status === 'completed' ? 'done' : 'error';
  const ran = t.startedAt ? (t.endedAt || now) - t.startedAt : 0;
