      const v = p >= 1 ? target.current : from + (target.current - from) * e;
      shownRef.current = v;
      setShown(v);
      raf.current = p < 1 ? requestAnimationFrame(tick) : null;
    };
    raf.current = requestAnimationFrame(tick);
  }, [value, ms]);
  useEffect(
    () => () => {
      if (raf.current != null) cancelAnimationFrame(raf.current);
    },
    [],
  );
