  background: var(--canvas);
  animation: boot-in var(--t-med) var(--ease);
}
.boot.leaving {
  animation: boot-out 320ms var(--ease-exit) forwards;
  pointer-events: none;
}
@keyframes boot-in {
  from {
    opacity: 0.999;
  }
}
@keyframes boot-out {
  to {
    opacity: 0;
    transform: scale(1.02);
  }
}
