  border-radius: var(--r-2);
}
.cfile-toggle > svg {
  flex: none;
  color: var(--text-3);
  transition: transform var(--t-med) var(--ease);
}
.cfile-name {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-weight: 500;
  white-space: nowrap;
}
.cfile-dir {
  font-family: var(--font-mono);
  font-size: 11.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  direction: rtl;
  text-align: left;
}
.fstat {
  flex: none;
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 650;
}
.fstat.s-M {
  color: var(--text-2);
  background: var(--fill-2);
}
.fstat.s-A,
.fstat.s-U {
  color: var(--ok);
  background: var(--ok-wash);
}
.fstat.s-D {
  color: var(--err);
  background: var(--err-wash);
}
.fstat.s-R {
  color: var(--info);
  background: var(--info-wash);
}
.cfile-body .diff {
  border-radius: 0;
  max-height: none;
  box-shadow: none;
  background: var(--canvas);
}
.cfile-body .diff-grid {
  padding: 4px 0 8px;
}
.cfile-note {
  padding: 12px 14px;
  font-size: var(--fs-small);
}
.notes-bar {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--raised);
  box-shadow: inset 0 1px 0 var(--hair-2);
  color: var(--text);
  font-size: var(--fs-small);
  animation: rise var(--t-med) var(--ease);
}

/* ---------------------------------------------------------------- files */

.files {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.files-body {
  flex: 1;
  min-height: 0;
  display: flex;
}
.tree {
